// function deleteUser(user, targetId)
// Agar user nahi: "No user"
// Agar user.admin nahi: "Not authorized"
// Agar targetId same hai user.id: "Cannot delete self"
// Warna "Deleted {targetId}"

solution:
function deleteUser(user, targetId) {
  if (!user) return "No user"
  if (!user.admin) return "Not authorized"
  if (targetId === user.id) return "Cannot delete self"
  return `Deleted ${targetId}`
}
